from pathlib import Path
import json
from html import escape
ROOT=Path(__file__).resolve().parent
data=json.loads((ROOT/'common-content.json').read_text(encoding='utf-8-sig'))
def esc(s): return escape(s,quote=True)
def svg(glyph):
    paths={
    'file':'<path d="M7 3h8l6 6v16H7zM15 3v7h6M10 15h7m-7 5h7"/>',
    'link':'<path d="m11 17-2 2a5 5 0 0 1-7-7l5-5a5 5 0 0 1 7 0m-2 3 2-2a5 5 0 0 1 7 7l-5 5a5 5 0 0 1-7 0m-1-1 8-8"/>',
    'folder':'<path d="M3 6h8l3 4h11v14H3zM3 11h22M10 17h9m-4-4 4 4-4 4"/>',
    'clipboard':'<path d="M9 5H5v20h18V5h-4M9 3h10v5H9zM9 14h10m-10 5h10"/>',
    'search':'<path d="m6 4 12 0 4 4v10l-4 4H6l-4-4V8zM20 20l6 6"/>',
    'mic':'<path d="M10 3h8v14h-8zM6 12v8l4 3h8l4-3v-8M14 23v4m-5 0h10"/>',
    'grid':'<path d="M3 3h8v8H3zM17 3h8v8h-8zM3 17h8v8H3zM17 17h8v8h-8z"/>',
    'settings':'<path d="M11 3h6l1 4 4 1 3 6-3 6-4 1-1 4h-6l-1-4-4-1-3-6 3-6 4-1zM10 10h8v8h-8z"/>',
    'info':'<path d="M3 3h22v22H3zM14 12v9m0-14v2"/>',
    }
    return '<svg viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="butt" stroke-linejoin="miter" aria-hidden="true">'+paths[glyph]+'</svg>'
def row(t,native):
    fail=t['state']=='failed'
    sub=('<span class="error-text">'+esc(t['error'])+'</span>') if fail else esc(t['description'])
    extra=t.get('englishName') or (t['description'] if fail else '')
    title=esc(t['name'])+('<span class="english">'+esc(extra)+'</span>' if extra else '')
    switch='<button class="switch" type="button" role="switch" aria-checked="'+str(t['state']=='running').lower()+'" aria-label="'+esc(t['name'])+'启停"'+(' disabled aria-describedby="everything-error"' if fail else '')+'><span class="thumb"></span></button>'
    setting='设置路径' if fail else data['settings']
    return '<article class="tool '+t['state']+'"><div class="tool-icon '+('native' if native else '')+'">'+svg(t['glyph'])+'</div><div class="tool-copy"><div class="tool-title">'+title+'</div><div class="description"'+(' id="everything-error"' if fail else '')+'>'+sub+'</div></div><div class="tool-control"><span class="status"><i></i>'+esc(t['stateText'])+'</span>'+switch+'</div><button class="row-setting" type="button" aria-label="'+esc(t['name']+setting)+'">'+esc(setting)+'</button></article>'
sections=[]
for i,group in enumerate(data['groups']):
    add='<button class="add-program" type="button"><span aria-hidden="true">+</span>'+esc(data['externalAction'])+'</button>' if i else ''
    sections.append('<section class="section"><div class="group-title"><h2>'+esc(group)+'<span class="count">3</span></h2>'+add+'</div>'+''.join(row(t,i==0) for t in data['tools'][i*3:i*3+3])+'</section>')
css='''
*{box-sizing:border-box;border-radius:0!important}html,body{margin:0;min-height:100vh}body{display:grid;place-items:center;background:#2B2C30;color:#EEE8DC;font-family:"Microsoft YaHei","微软雅黑",sans-serif;font-size:14px;-webkit-font-smoothing:antialiased}button{font:inherit;color:inherit;cursor:default}button:focus-visible{outline:2px solid #D6A2B0;outline-offset:3px}.app-window{width:980px;height:700px;display:grid;grid-template-rows:38px 620px 40px;border:1px solid #645C68;background:#211D24;box-shadow:0 20px 55px #0005}.titlebar{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #48414E;background:#18151C;padding-left:18px;font-size:13px;color:#C8C0CC}.app-title{display:flex;align-items:center;gap:9px}.brand-mark{width:12px;height:15px;display:block;border-left:3px solid #A55F72;border-top:2px solid #A55F72;border-bottom:2px solid #A55F72;position:relative}.brand-mark:after{content:"";position:absolute;height:2px;width:7px;background:#A55F72;top:5px;left:0}.window-actions{height:37px;display:flex}.window-actions button{width:44px;border:0;border-left:1px solid #2D2732;background:transparent;display:grid;place-items:center}.window-actions svg{width:12px;height:12px;stroke:currentColor;stroke-width:1;fill:none}.body{display:flex;min-height:0}.sidebar{width:198px;flex-shrink:0;background:#18151C;border-right:1px solid #48414E;display:flex;flex-direction:column;padding:19px 15px 16px}.identity{border:1px solid #48414E;border-bottom:2px solid #8D384F;margin:0 5px 23px;padding:8px 7px 12px;text-align:center;background:#1D1920}.portrait{width:140px;height:150px;object-fit:contain;display:block;margin:0 auto 5px}.brand{font-family:Georgia,"Times New Roman",serif;font-size:25px;line-height:32px;letter-spacing:1px;font-weight:400;color:#EEE8DC}.nav{height:40px;display:flex;align-items:center;gap:11px;padding:0 12px;width:100%;border:1px solid transparent;text-align:left;background:transparent;color:#BEB7C1;margin-bottom:7px}.nav svg{width:18px;height:18px}.nav.selected{background:#34212B;border-color:#715160;color:#EEE8DC;box-shadow:inset 3px 0 #B57386}.nav-bottom{margin-top:auto;border-top:1px solid #48414E;padding-top:13px}.main{width:780px;padding:24px 27px 0}.page-head{height:68px;display:flex;align-items:flex-start;justify-content:space-between;position:relative}.page-head h1{font-family:Georgia,"SimSun","宋体",serif;font-size:22px;line-height:32px;font-weight:400;margin:0;letter-spacing:1px}.page-head h1:after{content:"";display:block;width:30px;height:2px;background:#A55F72;margin-top:9px}.bulk-actions{display:flex;gap:9px;padding-top:1px}.bulk-actions button{height:33px;border:1px solid #706675;background:#29242E;padding:0 15px;font-size:14px}.bulk-actions .primary{background:#8D384F;border-color:#AF6B7E;color:#FFF3ED}.section+.section{margin-top:23px}.group-title{height:29px;display:flex;align-items:flex-start;justify-content:space-between;border-bottom:1px solid #756A7C}.group-title h2{font-family:Georgia,"SimSun","宋体",serif;font-weight:400;font-size:14px;line-height:21px;margin:0;color:#DDD5DF;letter-spacing:.2px}.count{font-family:Georgia,serif;color:#BEB7C1;font-size:13px;margin-left:11px}.add-program{display:flex;gap:7px;align-items:center;border:0;background:transparent;padding:0;font-size:13px;line-height:21px;color:#DBB0BE}.add-program span{font-family:Georgia,serif;font-size:19px;line-height:16px}.tool{height:70px;display:grid;grid-template-columns:29px minmax(0,1fr) 136px 62px;align-items:center;column-gap:13px;border-bottom:1px solid #403947}.tool:last-child{border-bottom:0}.tool-icon{width:27px;height:27px;color:#AEA3B4}.tool-icon svg{width:27px;height:27px}.tool-icon.native{color:#D3B3BD}.tool-title{font-size:16px;line-height:25px;font-weight:500;white-space:nowrap}.english{font-size:13px;font-family:Georgia,"Microsoft YaHei",sans-serif;color:#BEB7C1;font-weight:400;margin-left:9px}.description{font-size:14px;line-height:22px;color:#BEB7C1;white-space:nowrap}.error-text{color:#E7A9AC;font-size:13px}.tool-control{display:flex;align-items:center;justify-content:space-between;gap:10px}.status{display:flex;align-items:center;gap:7px;font-size:13px;color:#BEB7C1;white-space:nowrap}.status i{width:5px;height:5px;background:#918896;display:inline-block}.running .status{color:#DAD8C2}.running .status i{background:#B8C791}.failed .status{color:#E7A9AC}.failed .status i{background:#C57A8C}.switch{width:48px;height:24px;padding:3px;border:1px solid #716778;background:#17141B;display:block;position:relative;flex-shrink:0}.thumb{position:absolute;left:3px;top:3px;width:16px;height:16px;background:#A59AAE;border:1px solid #C1B5C8}.switch[aria-checked="true"]{background:#793249;border-color:#B67A8D}.switch[aria-checked="true"] .thumb{left:27px;background:#EEE8DC;border-color:#EEE8DC}.switch:disabled{opacity:.38}.row-setting{height:28px;border:0;border-bottom:1px solid #766276;padding:0;background:transparent;color:#D3B3BD;font-size:13px;white-space:nowrap}.failed .row-setting{color:#E7A9AC;border-bottom-color:#AD6E80}.footer{display:flex;align-items:center;justify-content:space-between;padding:0 23px 0 226px;border-top:1px solid #48414E;background:#1B171E;color:#BEB7C1;font-size:13px}.footer-note{display:flex;align-items:center;gap:8px}.footer-note svg{width:14px;height:14px;color:#BEB7C1}.footer-brand{font-family:Georgia,serif;color:#BEB7C1;font-size:14px;letter-spacing:1px}
'''
html='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=980, initial-scale=1"><title>Eous 助手 · 哥特墨绘</title><style>'''+css+'''</style></head><body><div class="app-window"><header class="titlebar"><div class="app-title"><i class="brand-mark" aria-hidden="true"></i><span>'''+esc(data['appName'])+'''</span></div><div class="window-actions"><button type="button" aria-label="最小化"><svg viewBox="0 0 12 12"><path d="M1 6h10"/></svg></button><button type="button" aria-label="最大化"><svg viewBox="0 0 12 12"><path d="M1.5 1.5h9v9h-9z"/></svg></button><button type="button" aria-label="关闭面板"><svg viewBox="0 0 12 12"><path d="m1.5 1.5 9 9m0-9-9 9"/></svg></button></div></header><div class="body"><aside class="sidebar"><div class="identity"><img class="portrait" src="assets/eous-gothic.png" alt="身穿炭黑外套、系橙色围巾的哥特蚀刻Eous"><div class="brand">Eous</div></div><nav><button type="button" class="nav selected" aria-current="page">'''+svg('grid')+'''工具总览</button></nav><div class="nav-bottom"><button type="button" class="nav">'''+svg('settings')+esc(data['settings'])+'''</button><button type="button" class="nav">'''+svg('info')+'''关于 Eous</button></div></aside><main class="main"><div class="page-head"><h1>工具总览</h1><div class="bulk-actions"><button type="button" class="primary">'''+esc(data['globalActions'][0])+'''</button><button type="button">'''+esc(data['globalActions'][1])+'''</button></div></div>'''+''.join(sections)+'''</main></div><footer class="footer"><div class="footer-note">'''+svg('info')+esc(data['footer'])+'''</div><span class="footer-brand">Eous</span></footer></div></body></html>'''
(ROOT/'gothic.html').write_text(html,encoding='utf-8')
print('Built gothic.html from common-content.json: 6 tools; 6 switches; uniform radius 0.')
